const r = await tools.exec_command({cmd:"pixi run --frozen -e detour-ai-augment-backend-api python - <<'PY'
import ast
import json
from collections import defaultdict
from pathlib import Path

path = Path('tasks/tasks-20260731-tighten-api/build/SPEC.ipynb')
nb = json.loads(path.read_text(encoding='utf-8'))
ordinals = defaultdict(int)

def source_text(cell):
    source = cell['source']
    return ''.join(source) if isinstance(source, list) else source

def display_arg(node):
    if isinstance(node, ast.Name):
        return node.id
    try:
        value = ast.literal_eval(node)
    except Exception:
        return ast.unparse(node)
    if isinstance(value, str):
        return value
    return repr(value)

def summarize(source):
    if 'def run_pytest' in source:
        return 'evidence runtime and deployment shell syntax'
    tree = ast.parse(source)
    calls = [
        node.value
        for node in tree.body
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call)
    ]
    if not calls:
        return 'executable evidence'
    call = calls[0]
    name = call.func.id if isinstance(call.func, ast.Name) else ast.unparse(call.func)
    args = [display_arg(argument) for argument in call.args]
    if name == 'run_pytest':
        return f"pytest: {args[0].split('::')[-1]}"
    if name == 'require_test_function':
        return f'required pytest: {args[1]}'
    if name == 'require_tokens':
        tokens = ast.literal_eval(call.args[1])
        first_token = tokens[0] if tokens else 'tokens'
        return f'source contract: {args[0]} contains {first_token}'
    if name == 'require_no_tokens':
        return f'source contract: {args[0]} excludes forbidden tunnel'
    if name == 'require_order':
        return f'source order: {args[0]}'
    if name == 'require_no_ellipsis':
        return f'implementation complete: {args[0]}'
    if name == 'require_file':
        return f"required file: {Path(args[0]).name}"
    return f'{name}: {args[0]}' if args else name

for cell in nb['cells']:
    if cell['cell_type'] != 'code':
        continue
    task_lines = cell['metadata']['task_lines']
    first = task_lines[0]
    ordinals[first] += 1
    cell['metadata']['evidence_id'] = f'E{first:03d}.{ordinals[first]:02d}'
    cell['metadata']['summary'] = summarize(source_text(cell))

path.write_text(
    json.dumps(nb, indent=1, ensure_ascii=False) + '\n',
    encoding='utf-8',
)
PY","workdir":"/Volumes/home/aicode/2026-01-02_enrich_full_df","yield_time_ms":10000,"max_output_tokens":4000});
text(r.output);

